}

// DupExpr: launch 256 CTAs x 1024 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 128 B (v0: disjoint offsets, zero reuse)
