    auto c0 = 0.0f;
    auto c1 = 0u;
    auto v2 = R;
    auto c2 = 1u;
    auto v3 = C;
    auto c3 = 2u;
    auto v4 = 8u;
    auto v5 = grid_map0.index(0u);
    auto c4 = 16u;
    auto v6 = (v5 * c4);
    auto v7 = grid_map0.index(1u);
    auto v8 = (v7 * c4);
    auto v9 = thread_map1.index(0u);
    auto v10 = (v9 * c4);
    auto v11 = thread_map1.lane_id();
    auto v12 = (v11 + c2);
    auto v13 = (v12 * c2);
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c0, DupExprCombine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 32u));
