    for (auto R_it0 = tca::rt::CtaIterator(grid_map0, 0u, 16u, 0u, 256u, v2); R_it0.Has(); R_it0.Next()) {
      auto v14 = (v6 + R_it0.Index());
      auto v15 = tca::rt::umin(v14, v2);
      auto v16 = (v2 - v15);
